# 1. 带 fixture 的测试
import pytest
from myapp import create_app, database

@pytest.fixture(scope="module")
def app():
    app = create_app(testing=True)
    yield app
    app.cleanup()

@pytest.fixture
def client(app):
    return app.test_client()

def test_api(client):
    response = client.get("/api/health")
    assert response.status_code == 200

# 2. 参数化与 Fixture 组合
@pytest.mark.parametrize("role,expected", [
    ("admin", 200),
    ("user", 403),
    ("guest", 401),
])
def test_permissions(client, auth_token, role, expected):
    token = auth_token(role)
    response = client.get("/api/admin", headers={"Authorization": token})
    assert response.status_code == expected

