# 4. 使用 fixture 控制测试顺序依赖
@pytest.fixture
def created_user(db_session):
    user = User(name="test")
    db_session.add(user)
    db_session.commit()
    yield user
    db_session.delete(user)
    db_session.commit()

def test_user_exists(created_user):
    assert User.query.get(created_user.id) is not None
